@startuml

class RepairShop {
  + name : string
  + address : string
  + numberOfEmployees : int
}

class Employee {
  + taxCode : string
  + address : string
  + phoneNumber : string
  + yearsOfService : int
}

class Director extends Employee {
  + age : int
}

class Repair {
  + code : string
  + checkInTime : datetime
  + checkInDate : date
  + returnTime : time
  + returnDate : date
}

class Vehicle {
  + model : string
  + type : string
  + licensePlate : string
  + yearOfRegistration : int
}

class Owner {
  + taxCode : string
  + address : string
  + phoneNumber : string
}

class Manager {
}

class AccountingOffice {
}

"1" -- "*" RepairShop : manages
"1" -- "*" Employee : employs
"1" -- "1" Director : directs
"1" -- "*" Repair : performs
"1" -- "1" Vehicle : undergoes
"1" -- "1" Owner : owns
"1" -- "*" Vehicle : owns
"1" -- "*" Repair : involves
"1" -- "1" AccountingOffice : receives results
"1" -- "1" Manager : performs analyses

@enduml

